function useTypewriter(text, speed = 45, startDelay = 300) {
  const [out, setOut] = useState("");
  useEffect(() => {
    let i = 0;
    let interval;
    const timeout = setTimeout(() => {
      interval = setInterval(() => {
        i += 1;
        setOut(text.slice(0, i));
        if (i >= text.length) clearInterval(interval);
      }, speed);
    }, startDelay);
    return () => {
      clearTimeout(timeout);
      clearInterval(interval);
    };
  }, [text, speed, startDelay]);
  return out;
}

function NetworkBackdrop() {
  const nodes = [
    [60, 80], [220, 40], [380, 120], [140, 220], [320, 260],
    [60, 340], [400, 360], [240, 420], [480, 200], [500, 60],
  ];
  const edges = [
    [0, 1], [1, 2], [1, 3], [3, 4], [2, 4], [3, 5], [4, 6], [4, 7], [2, 8], [8, 9], [1, 9],
  ];
  return (
    <svg
      viewBox="0 0 540 460"
      style={{
        position: "absolute",
        inset: 0,
        width: "100%",
        height: "100%",
        opacity: 0.35,
      }}
      preserveAspectRatio="xMidYMid slice"
    >
      {edges.map(([a, b], i) => (
        <line
          key={i}
          x1={nodes[a][0]}
          y1={nodes[a][1]}
          x2={nodes[b][0]}
          y2={nodes[b][1]}
          stroke="#00f5ff"
          strokeWidth="1"
          className="edge"
          style={{ animationDelay: `${i * 0.25}s` }}
        />
      ))}
      {nodes.map(([x, y], i) => (
        <circle
          key={i}
          cx={x}
          cy={y}
          r={i % 3 === 0 ? 4 : 2.5}
          fill={i % 3 === 0 ? "#ff2ec4" : "#00f5ff"}
          className="node"
          style={{ animationDelay: `${i * 0.3}s` }}
        />
      ))}
    </svg>
  );
}

